PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS product_attribute_option_overrides(product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,option_id TEXT NOT NULL REFERENCES product_attribute_options(id) ON DELETE CASCADE,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),is_default INTEGER NOT NULL DEFAULT 0 CHECK(is_default IN(0,1)),price_delta_irt INTEGER NOT NULL DEFAULT 0 CHECK(price_delta_irt>=0),PRIMARY KEY(product_id,option_id));
CREATE INDEX IF NOT EXISTS idx_product_option_overrides_product ON product_attribute_option_overrides(product_id,active);
CREATE TABLE IF NOT EXISTS product_category_assignments(product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE,category_id TEXT NOT NULL REFERENCES categories(id) ON DELETE CASCADE,sort_order INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(product_id,category_id));
CREATE INDEX IF NOT EXISTS idx_product_category_assignments_category ON product_category_assignments(category_id,sort_order);
